style.css:
@-moz-document domain("excel.office.com"), domain("office.live.com") {
/* 1. Global Modern Variables & Typography */
  :root {
    --bg-main: #0f172a !important;
    --bg-surface: #1e293b !important;
    --border-color: #334155 !important;
    --accent-emerald: #10b981 !important;
    --text-primary: #f8fafc !important;
    --text-muted: #94a3b8 !important;
  }

  body, html, #WacFrame {
    background-color: var(--bg-main) !important;
    color: var(--text-primary) !important;
    font-family: 'Segoe UI Variable', 'Inter', -apple-system, sans-serif !important;
  }

  /* 2. Top Ribbon & Header Glassmorphism */
  #headerContainer, .ewa-ribbon, .od-Header, #WacHeader {
    background: rgba(15, 23, 42, 0.85) !important;
    backdrop-filter: blur(12px) !important;
    -webkit-backdrop-filter: blur(12px) !important;
    border-bottom: 1px solid var(--border-color) !important;
  }

  /* 3. Sleek Formula Bar */
  .ewa-formulaBar, #FormulaBarContainer {
    background-color: var(--bg-surface) !important;
    border: 1px solid var(--border-color) !important;
    border-radius: 8px !important;
    color: var(--text-primary) !important;
    margin: 4px 8px !important;
    box-shadow: 0 4px 6px -1px rgba(0, 0, 0, 0.3) !important;
  }

  /* 4. Canvas & Spreadsheet Grid Dark Inversion */
  .ewa-canvas, #GridRowHeaderCanvas, #GridColumnHeaderCanvas {
    background-color: var(--bg-main) !important;
    filter: invert(0.92) hue-rotate(180deg) contrast(1.08) brightness(0.92) !important;
  }

  /* Preserve original chart & image colors from inversion */
  img, svg, canvas.chart-canvas, .ewa-chart {
    filter: invert(1) hue-rotate(180deg) !important;
  }

  /* 5. Custom Minimalist Scrollbars */
  ::-webkit-scrollbar {
    width: 8px !important;
    height: 8px !important;
  }
  ::-webkit-scrollbar-track {
    background: var(--bg-main) !important;
  }
  ::-webkit-scrollbar-thumb {
    background: #334155 !important;
    border-radius: 4px !important;
  }
  ::-webkit-scrollbar-thumb:hover {
    background: var(--accent-emerald) !important;
  }
}
